<?php
 namespace QQWorld\Framework\Filesystem; class DriverPool { const FILE = 'file'; const HTTP = 'http'; const HTTPS = 'https'; const ZLIB = 'compress.zlib'; protected $types = [ self::FILE => \QQWorld\Framework\Filesystem\Driver\File::class, self::HTTP => \QQWorld\Framework\Filesystem\Driver\Http::class, self::HTTPS => \QQWorld\Framework\Filesystem\Driver\Https::class, self::ZLIB => \QQWorld\Framework\Filesystem\Driver\Zlib::class, ]; private $pool = []; public function __construct($extraTypes = []) { foreach ($extraTypes as $code => $typeOrObject) { if (is_object($typeOrObject)) { $type = get_class($typeOrObject); $object = $typeOrObject; } else { $type = $typeOrObject; $object = false; } if (!is_subclass_of($type, \QQWorld\Framework\Filesystem\DriverInterface::class)) { throw new \InvalidArgumentException("The specified type '{$type}' does not implement DriverInterface."); } $this->types[$code] = $type; if ($object) { $this->pool[$code] = $typeOrObject; } } } public function getDriver($code) { if (!isset($this->types[$code])) { $code = self::FILE; } if (!isset($this->pool[$code])) { $class = $this->types[$code]; $this->pool[$code] = new $class(); } return $this->pool[$code]; } } 